/// `events::decide_hint` as this binary runs `decide`.
fn decide_hint(e: &Event, t: &Ticket) -> Option<String> {
    events::decide_hint(e, t, &decide_command())
}

/// `show`'s lines for a document a per-lane stage writes once per lane.
fn print_lane_files(name: &str, files: &[dispatch_control::LaneFile]) -> Result<()> {
    for f in files {
        let lane = f
            .lane
            .as_ref()
            .map_or_else(String::new, |l| format!(" ({l})"));
        say!("  {name}{lane}: {}", f.path.display());
        if f.reviewing {
            let round = f.round.map_or_else(String::new, |n| format!(", round {n}"));
            say!("    (reviewed copy{round}, review open)");
        }
    }
    Ok(())
}

fn show(args: &[&str]) -> Result<()> {
    let f = Flags::parse(args, &[], &["--json"]);
    let runner = offline_runner()?;
    let t = runner.load_ticket(f.one())?;
    let pipeline = runner.pipeline_of(&t).ok();
    let mut view = ticket_view(&t, pipeline.as_ref());
    view.paths = ticket_paths(&t, pipeline.as_ref());
    if f.on("--json") {
        say!("{}", serde_json::to_string_pretty(&view)?);

    pub plan_files: Vec<LaneFile>,
    /// The notes, the same way.
    pub notes_files: Vec<LaneFile>,
}

/// One lane's copy of a ticket's document, or the ticket's only one.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct LaneFile {
    /// The lane it was written in; none for a stage that runs once.
    pub lane: Option<String>,
    /// The stage whose attempt wrote it.
    pub stage: String,
    /// Where it is.
    pub path: PathBuf,
    /// Written by a plan review whose review is still open, so the
    /// planner may still be editing it.
    pub reviewing: bool,
    /// The newest round of the plan review that wrote it, as
    /// `PathsView::plan_round` counts; none for any other writer.
    pub round: Option<u32>,
}

/// One plan review round's files.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]

/// The format of a ticket or project record this build reads and
/// writes. A record carries it as `version`; one written before records
/// carried a version reads as 0 and is brought up by `migrate`. A
/// record above it was written by a newer `dispatch` and is refused
/// both ways, so this build never drops fields it does not know.
pub const RECORD_VERSION: u32 = 28;

/// A lock file held while this lives: the writer lock, the runner's
/// claim, or a ticket's close.
#[derive(Debug)]
pub struct Lock(File);

